import '../styles.css';
import selectedLogoSource from './assets/brand/reliefvue-elephant-selected.png';
import chiangMaiConcept from './assets/editorial/chiang-mai-concept.png';
import householdConcept from './assets/editorial/household-concept.png';
import {createDemo,submitClaim,decideClaim,completePayout,donateSample,totals,type ClaimStatus} from './demo-state';
import {localize,type Locale} from './i18n';

if(location.hash==='#technical') {
 const exit=document.createElement('a');exit.href=location.pathname;exit.textContent='← Return to guided hackathon demo';exit.className='technical-return';document.body.prepend(exit);
 void import('./technical');
} else start();

function start(){
 const root=document.querySelector<HTMLDivElement>('#app');if(!root)throw Error('Application root missing');const app=root;
 let state=createDemo();let page=location.hash.slice(1)||'home';let message='';let step=0;let entry='create';let edit=false;let decision='approve';let reviewCase='current';let locale:Locale='en';let walletPreview=false;
 let donor={route:'sol' as 'sol'|'local',amount:.25,support:0};
 const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
 const sol=(n:number)=>n.toLocaleString('en-US',{maximumFractionDigits:9});
 const btn=(label:string,action:string,kind='primary',disabled=false)=>`<button class="button ${kind}" data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
 const link=(label:string,target:string,kind='secondary')=>`<a class="button ${kind}" href="#${target}">${label}</a>`;
 const badge=(label:string,kind='')=>`<span class="badge ${kind}">${esc(label)}</span>`;
 const intro=(tag:string,title:string,text:string)=>`<div class="page-intro narrow"><p class="eyebrow">${tag}</p><h1 tabindex="-1">${title}</h1><p>${text}</p></div>`;
 const privacy=()=>`<p class="demo-inline">Use made-up details. Do not enter real ID numbers or documents. Entries clear when you refresh or reset.</p>`;
 const sample=()=>``;
 const field=(id:string,label:string,value:string,placeholder='',required=true)=>`<label for="${id}">${label}</label><input id="${id}" name="${id}" maxlength="100" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?'required':''} autocomplete="off">`;
 function go(next:string){message='';if(page===next){render(true);return;}location.hash=next;}
 const publicResponse={get received(){return totals(state).received},get reserve(){return totals(state).reserve},budget:12000,grant:.8,get paid(){return totals(state).distributed},get left(){return totals(state).remainingAllocation},get households(){return 9600+(state.claim?.status==='paid'?1:0)}};
 const transfers=[['RV–09421','Household grant',.8,'7L8c…G4p2','Mae Rim'],['RV–09420','Household grant',.8,'3Mqa…8Vn6','Mae Rim'],['RV–09419','Reserve donation',120,'Relief reserve','Thailand'],['RV–09418','Household grant',.8,'9Pxt…2Jf7','Mae Rim'],['RV–09417','Household grant',.8,'5Hrn…4Qy8','Mae Rim'],['RV–09416','Reserve donation',45,'Relief reserve','Thailand'],['RV–09415','Household grant',.8,'6Buv…3Ks9','Mae Rim'],['RV–09414','Household grant',.8,'8Fje…7Xp1','Mae Rim'],['RV–09413','Reserve donation',88,'Relief reserve','Thailand'],['RV–09412','Reserve donation',21,'Relief reserve','Thailand']] as const;
 let ledgerFilter:'all'|'grants'|'donations'='all';let replayCursor=3;let replayPaused=false;
 const scenarioAlerts=[['STORM WATCH','Heavy storm watch near Mae Rim','Today · 09:42 · Example bulletin'],['FLOOD REPORT','Homes inundated in Mae Rim','Today · 10:06 · Example local report'],['LANDSLIDE WATCH','Access road at risk north of Chiang Mai','Today · 10:18 · Example area advisory'],['RESPONSE REVIEW','Mae Rim household response under review','Today · 10:31 · Demo response update']] as const;let alertsPaused=false;
 function summary(){return `<div class="fund-metrics"><div><span>Relief reserve</span><strong>${sol(publicResponse.reserve)} <small>SOL</small></strong></div><div><span>Mae Rim budget</span><strong>${sol(publicResponse.budget)} <small>SOL</small></strong></div><div><span>Per household</span><strong>${sol(publicResponse.grant)} <small>SOL</small></strong></div><div><span>Grants sent</span><strong>${sol(publicResponse.paid)} <small>SOL</small></strong><em>${publicResponse.households.toLocaleString('en-US')} <span>households</span></em></div><div><span>Allocation left</span><strong>${sol(publicResponse.left)} <small>SOL</small></strong></div></div><p class="fund-reconcile">Sample accounting: ${sol(publicResponse.received)} SOL received = ${sol(publicResponse.reserve)} in reserve + ${sol(publicResponse.paid)} distributed. The ${sol(publicResponse.budget)} SOL response budget includes ${sol(publicResponse.left)} SOL still allocated.</p>`;}
 function transferMarkup([ref,type,amount,wallet,area]:readonly [string,string,number,string,string],fresh=false){return `<li class="transfer-row ${fresh?'new':''}"><span class="transfer-kind ${type==='Household grant'?'grant':'donation'}" aria-hidden="true">${type==='Household grant'?'↗':'＋'}</span><span class="transfer-context"><strong>${esc(type)}</strong><small>${esc(area)} · ${esc(ref)}</small></span><span class="transfer-destination"><small>To</small><strong>${esc(wallet)}</strong></span><span class="transfer-amount">${sol(amount)} <small>SOL</small></span><span class="transfer-status ${type==='Household grant'?'sent':'received'}">${type==='Household grant'?'Sent':'Received'}</span></li>`;}
 function laneMarkup([ref,type,amount,wallet,area]:readonly [string,string,number,string,string]){return `<li class="lane-row"><div class="lane-main"><strong>${type==='Household grant'?'Grant sent':'Reserve received'}</strong><small>${esc(area)} · ${esc(ref)}</small></div><div class="lane-route"><span>${type==='Household grant'?'To wallet':'To reserve'}</span><strong>${esc(wallet)}</strong></div><div class="lane-amount">${sol(amount)} <small>SOL</small></div></li>`;}
 function replayRows(){const demoRows=state.activity.filter(a=>a.step==='Your demo contribution'||a.step==='Walkthrough outcome').map(a=>[a.ref,a.type==='Donation'?'Reserve donation':a.type,a.amount,a.type==='Donation'?'Relief reserve':'Example wallet','Your session'] as const);return [...demoRows,...transfers];}
 function ledgerFeed(full=false){const rows=replayRows().filter(a=>ledgerFilter==='all'||(ledgerFilter==='grants'?a[1]==='Household grant':a[1]!=='Household grant'));if(!full){const received=rows.filter(a=>a[1]!=='Household grant');const sent=rows.filter(a=>a[1]==='Household grant');const lane=(label:string,kind:string,data:typeof rows)=>`<div class="movement-lane" data-lane="${kind}"><div class="movement-lane-head"><span class="lane-signal ${kind}" aria-hidden="true"></span><strong>${label}</strong><span>${kind==='received'?'Into relief reserve':'To household wallets'}</span></div><div class="lane-window"><ul aria-live="off">${Array.from({length:4},(_,i)=>laneMarkup(data[((i+replayCursor)%data.length+data.length)%data.length])).join('')}</ul></div></div>`;return `<section class="ledger-panel ledger-replay" aria-label="Fictional fund movements"><div class="ledger-head"><div><p class="ledger-kicker">SCENARIO REPLAY · SOLANA FUND FLOW</p><h2>From donations to household wallets.</h2><p>Watch eight example movements turn over below: contributions arrive, approved grants leave, and each amount has a destination.</p></div><div class="ledger-controls"><button type="button" data-action="ledger-pause" aria-pressed="${replayPaused}">${replayPaused?'Resume replay':'Pause replay'}</button></div></div><div class="movement-lanes">${lane('Received','received',received)}${lane('Grants sent','sent',sent)}</div><div class="ledger-bottom"><span>Fictional wallet fragments and movements. No blockchain transfers are claimed.</span><a href="#activity">Open full activity ↗</a></div></section>`;}const content=Array.from({length:Math.min(8,rows.length)},(_,i)=>transferMarkup(rows[((i+replayCursor)%rows.length+rows.length)%rows.length])).join('');return `<section class="ledger-panel ledger-full" aria-label="Sample fund movements"><div class="ledger-head"><div><p class="ledger-kicker">SCENARIO REPLAY</p><h2>The public fund record</h2><p>Browse the sample response as it unfolds. Filter contributions and grants; amounts and destinations remain visible without household names.</p></div><div class="ledger-controls"><button type="button" data-action="ledger-pause" aria-pressed="${replayPaused}">${replayPaused?'Resume replay':'Pause replay'}</button></div></div><div class="ledger-filters" role="group" aria-label="Filter fund activity"><button data-action="ledger-all" aria-pressed="${ledgerFilter==='all'}">All</button><button data-action="ledger-grants" aria-pressed="${ledgerFilter==='grants'}">Grants</button><button data-action="ledger-donations" aria-pressed="${ledgerFilter==='donations'}">Donations</button></div><div class="transfer-labels" aria-hidden="true"><span>Movement</span><span>Destination</span><span>Amount</span><span>Status</span></div><div class="transfer-window full"><ul class="transfer-list" aria-live="off">${content}</ul></div><p class="ledger-note">Fictional references and wallet fragments; no blockchain transactions are claimed.</p></section>`;}
 function advanceReplay(list:HTMLUListElement,markup:string,limit:number){
  const template=document.createElement('template');template.innerHTML=markup;
  const next=template.content.firstElementChild as HTMLElement|null;if(!next)return;
  const previous=list.firstElementChild as HTMLElement|null;
  list.prepend(next);localize(next,locale);
  const distance=previous?previous.getBoundingClientRect().top-next.getBoundingClientRect().top:next.getBoundingClientRect().height;
  const animation=list.animate([{transform:`translateY(-${distance}px)`},{transform:'translateY(0)'}],{duration:620,easing:'cubic-bezier(.22,.75,.25,1)'});
  animation.finished.then(()=>{if(list.isConnected&&list.contains(next))while(list.children.length>limit)list.lastElementChild?.remove();}).catch(()=>{});
 }
 setInterval(()=>{
  if(replayPaused||document.hidden||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  if(page!=='home'&&page!=='overview'&&page!=='activity')return;
  replayCursor--;
  if(page==='home'||page==='overview'){
   app.querySelectorAll<HTMLUListElement>('.movement-lane ul').forEach((list,index)=>{
    const data=replayRows().filter(t=>index===1?t[1]==='Household grant':t[1]!=='Household grant');
    if(data.length)advanceReplay(list,laneMarkup(data[((replayCursor%data.length)+data.length)%data.length]),list.children.length);
   });
  }else{
   const list=app.querySelector<HTMLUListElement>('.ledger-full .transfer-list');if(!list)return;
   const data=replayRows().filter(t=>ledgerFilter==='all'||(ledgerFilter==='grants'?t[1]==='Household grant':t[1]!=='Household grant'));
   if(data.length)advanceReplay(list,transferMarkup(data[((replayCursor%data.length)+data.length)%data.length]),list.children.length);
  }
 },2600);
 function activityTable(){return ledgerFeed(true);}
 function activityCharts(){
  const received=publicResponse.received, reserve=publicResponse.reserve, paid=publicResponse.paid, left=publicResponse.left;
  const stages=[['Response opened',0],['First households',800],['More households',2880],['Current replay',paid]] as const;
  const high=Math.max(8000,Math.ceil(paid/2000)*2000);
  const points=stages.map(([,value],i)=>[54+i*177,188-(value/high)*148] as const);
  const line=points.map(([x,y],i)=>`${i?'L':'M'}${x},${y.toFixed(1)}`).join(' ');
  const area=`${line} L585,188 L54,188 Z`;
  const sentAngle=(paid/publicResponse.budget*360).toFixed(2);
  const chartDescription=locale==='th'?`ตัวอย่างเงินช่วยเหลือสะสม: เริ่ม 0, ช่วงแรก 800, เพิ่มขึ้น 2,880 และปัจจุบัน ${sol(paid)} SOL`:`Illustrative cumulative grants: 0, 800, 2,880, then ${sol(paid)} SOL across four response stages.`;
  return `<section class="activity-visuals" aria-label="Illustrative fund charts"><div class="activity-visuals-head"><div><p class="eyebrow">THE RESPONSE IN NUMBERS</p><h2>See the reserve, the grants, and what remains.</h2></div><p>Fictional Mae Rim response. These charts explain the example figures; they do not depict live Solana transactions.</p></div><div class="activity-kpis"><article><span>Total received</span><strong>${sol(received)} <small>SOL</small></strong><p>Into the relief reserve in this scenario</p></article><article><span>Household grants sent</span><strong>${sol(paid)} <small>SOL</small></strong><p>${locale==='th'?`${publicResponse.households.toLocaleString('en-US')} ครัวเรือนตัวอย่าง · ${sol(publicResponse.grant)} SOL ต่อครัวเรือน`:`${publicResponse.households.toLocaleString('en-US')} example households · ${sol(publicResponse.grant)} SOL each`}</p></article><article><span>Reserve available</span><strong>${sol(reserve)} <small>SOL</small></strong><p>After the example grants</p></article></div><div class="activity-chart-grid"><figure class="activity-chart-card activity-trend"><figcaption><strong>Grants reached households</strong><span>Illustrative cumulative progress · SOL</span></figcaption><div class="chart-legend"><i class="chart-swatch purple" aria-hidden="true"></i><span>Household grants sent</span></div><svg class="activity-line-chart" viewBox="0 0 640 226" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(chartDescription)}"><defs><linearGradient id="activity-area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#6840B5" stop-opacity=".17"/><stop offset="100%" stop-color="#6840B5" stop-opacity=".02"/></linearGradient></defs><path d="M54 40H585 M54 114H585 M54 188H585" class="activity-gridline"/><path d="${area}" fill="url(#activity-area)"/><path d="${line}" class="activity-trend-line"/>${points.map(([x,y])=>`<circle cx="${x}" cy="${y.toFixed(1)}" r="4.5" class="activity-point"/>`).join('')}<text x="9" y="44">${sol(high)}</text><text x="18" y="118">${sol(high/2)}</text><text x="40" y="192">0</text></svg><div class="activity-x-labels"><span>Opened</span><span>First grants</span><span>More verified</span><span>Current</span></div><div class="activity-data-table"><table><caption>Illustrative cumulative grants by response stage, in SOL</caption><thead><tr><th scope="col">Stage</th><th scope="col">Grants sent (SOL)</th></tr></thead><tbody>${stages.map(([name,value])=>`<tr><th scope="row">${name}</th><td>${sol(value)}</td></tr>`).join('')}</tbody></table></div></figure><figure class="activity-chart-card activity-allocation"><figcaption><strong>Mae Rim response budget</strong><span>Grant allocation in this fictional event</span></figcaption><div class="allocation-graphic"><div class="allocation-donut" style="--sent-angle:${sentAngle}deg" role="img" aria-label="${esc(locale==='th'?`งบตอบสนอง 12,000 SOL จ่ายแล้ว ${sol(paid)} SOL เหลือ ${sol(left)} SOL`:`12,000 SOL response budget: ${sol(paid)} SOL sent to households and ${sol(left)} SOL still allocated.`)}"><div><span>Event budget</span><strong>${sol(publicResponse.budget)}</strong><small>SOL</small></div></div><div class="allocation-legend"><div><i class="chart-swatch purple" aria-hidden="true"></i><span>Grants sent<strong>${sol(paid)} SOL</strong></span></div><div><i class="chart-swatch coral" aria-hidden="true"></i><span>Still allocated<strong>${sol(left)} SOL</strong></span></div></div></div><p class="activity-chart-note">${locale==='th'?`เงินช่วยเหลือตัวอย่าง ${sol(publicResponse.grant)} SOL ต่อครัวเรือนที่ได้รับอนุมัติ ยอดคงเหลือเป็นส่วนหนึ่งของงบเหตุการณ์นี้ ไม่ใช่เงินก้อนอื่น`:`One fixed ${sol(publicResponse.grant)} SOL example grant per approved household. The remaining allocation is part of this event budget, not an extra fund.`}</p></figure></div></section>`;
 }
 function home(){return `<div class="rv-home"><section class="rv-hero"><p class="eyebrow">A CHIANG MAI RESPONSE · INTERACTIVE DEMO</p><h1 tabindex="-1">When disaster strikes, help should already be ready.</h1><p class="rv-hero-lead">ReliefVue proposes a SOL reserve funded before disaster. After a serious flood, households could request one fixed grant. People review eligibility; Solana makes every fund movement visible.</p><div class="rv-hero-actions">${link('Get help','receiver','primary')}${link('Support the reserve','donate','secondary')}</div><figure class="rv-hero-image"><img src="${chiangMaiConcept}" alt="Illustrative scene of Chiang Mai neighbours helping one another after flooding"><figcaption><strong>Help for households. A record anyone can check.</strong><span>Concept image; no actual ReliefVue response is depicted.</span></figcaption></figure></section><div class="rv-impact"><div class="impact-intro"><span>IN THIS FICTIONAL MAE RIM RESPONSE</span><strong>See the scale of one prepared reserve.</strong></div><div class="impact-metric"><strong>${publicResponse.households.toLocaleString('en-US')}</strong><span>households helped</span></div><div class="impact-metric"><strong>${sol(publicResponse.grant)} SOL</strong><span>per household in this demo</span></div><a href="#activity">Trace the example grants <span aria-hidden="true">↗</span></a></div><section class="rv-story"><div class="rv-story-heading"><div><p class="eyebrow">WHAT A GRANT CAN MAKE POSSIBLE</p><h2>A little freedom when plans change overnight.</h2></div><p>A household may need drinking water today, transport tomorrow, or materials for a damaged home. A cash grant lets them decide what is urgent, when it is safe to buy it.</p></div><article><img src="${householdConcept}" alt="Illustrative family selecting food and water at a neighbourhood shop after flooding"><div><p class="eyebrow">ILLUSTRATIVE HOUSEHOLD SCENE · MAE RIM</p><h3>Support goes to the household. The choice stays with them.</h3><p>In this proposed service, a verified household could receive one fixed emergency grant. The amount and destination would appear in the public fund record, while names and documents stay private.</p><a href="#receiver">Explore the household journey →</a></div></article></section><section class="fund-section"><div class="fund-intro"><div><p class="eyebrow">PUBLIC FUND RECORD</p><h2>Every transfer visible. Household details private.</h2><p>See a sample reserve, response budget and household payouts side by side.</p></div><a href="#activity">Open the full record ↗</a></div>${summary()}${ledgerFeed()}</section><section class="service-path"><p class="eyebrow">HOW IT WORKS</p><h2>From prepared funds to household help.</h2><div class="path-grid"><article><span>01</span><h3>Prepare</h3><p>Households can register ahead of time. Donors keep the relief reserve ready.</p></article><article><span>02</span><h3>Verify</h3><p>People check the affected area, evidence and each household’s eligibility.</p></article><article><span>03</span><h3>Support</h3><p>One fixed grant goes to an approved household. The fund movement is public.</p></article></div><a href="#how" class="text-link">See the full process and FAQs →</a></section><section class="home-faq"><div><p class="eyebrow">COMMON QUESTIONS</p><h2>Before you begin</h2></div><div class="faq-stack"><details><summary>Who can request support?</summary><p>A household living in an approved affected area could apply, including renters and legally resident foreign nationals. Checks are private.</p></details><details><summary>Is the grant per person?</summary><p>No. One fixed grant is planned per verified household per response. Separate rented rooms may be separate households after review.</p></details><details><summary>What can donors see?</summary><p>Fund amounts and wallet destinations, without names, household addresses or documents.</p></details></div></section></div>`;}
 function how(){return `${intro('HOW IT WORKS','From a ready reserve to household help.','A response opens after serious impact and the affected area are reviewed by people.')}<section class="how-steps">${[['Prepare','Donations build a SOL relief reserve. Households can set up details before an emergency.'],['Check the event','Official sources and local reports inform review. AI can flag leads; people authorize the affected area and budget.'],['Verify the household','Identity, usual residence and household uniqueness are checked privately. A shared address alone does not prove duplication.'],['Send the grant','One approved household receives the fixed event amount. Baht conversion remains a future provider option.'],['Follow the funds','Public records show amounts and wallet destinations without private household evidence.']].map(([title,body],i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><h2>${title}</h2><p>${body}</p></div></article>`).join('')}</section><div class="how-actions">${link('Get help','receiver','primary')}${link('Donate','donate','secondary')}</div><section class="home-faq"><div><p class="eyebrow">FAQ</p><h2>Good to know</h2></div><div class="faq-stack"><details><summary>Does a weather warning release funds?</summary><p>No. Forecasts can put an area on watch. Observed serious impact and human authorization are needed for a response.</p></details><details><summary>What if I rent one room?</summary><p>A reviewer checks the usual residence and evidence. Separate rooms may be separate households.</p></details><details><summary>Can I choose how to use the grant?</summary><p>The grant is intended as flexible emergency support for needs such as food, water, transport or urgent repairs.</p></details><details><summary>Are my details public?</summary><p>No names, addresses or documents belong in the public fund record. A wallet address does not guarantee anonymity.</p></details></div></section>`;}
 function receiver(){return `${intro('HOUSEHOLD ACCOUNT','Get help for your household.','Create a profile before an emergency, or start when your area is affected.')} ${privacy()}<section class="work-card"><div class="button-row" aria-label="Demo account route">${btn('Create account','create',entry==='create'?'primary':'secondary')}${btn('Sign in','signin',entry==='signin'?'primary':'secondary')}</div><h2>${entry==='create'?'Create your household profile':'Open your household account'}</h2><p>Start with a name for this walkthrough. No email or password is needed.</p><form id="entry-form">${field('name','Display name',state.receiver.name,'Example name')}<div class="button-row"><button class="button primary">${entry==='create'?'Continue':'Open dashboard'}</button>${btn('Use example household','sample-profile','secondary')}</div></form><a class="text-link" href="#recovery">Can’t access your account?</a></section>`;}
 function recovery(){return `${intro('ACCOUNT RECOVERY · FUTURE SERVICE','Help getting back into your account.','The planned real service would offer registered phone/email recovery, then human re-verification if those channels were lost.')}<section class="work-card"><p>Login recovery cannot recreate a lost self-custody wallet key. No real account or recovery service exists in this demo.</p>${link('Return to demo sign in','receiver','primary')}</section>`;}
 function walletGuide(){return `<section class="wallet-guide" aria-label="Payout and wallet preview"><div class="wallet-guide-head"><div><p class="eyebrow">WHEN A CLAIM IS APPROVED</p><h2>Where would your grant go?</h2><p>Choose a preference now. In a real service, you would connect a wallet or use a qualified conversion provider after approval. This demo connects neither.</p></div><span class="wallet-demo-tag">DEMO ONLY</span></div><div class="wallet-guide-options"><button type="button" data-action="wallet-route-sol" aria-pressed="${state.receiver.route==="sol"}"><strong>Keep SOL</strong><span>Send to a verified Solana wallet. Its baht value can change.</span></button><button type="button" data-action="wallet-route-baht" aria-pressed="${state.receiver.route==="baht"}"><strong>Convert to baht</strong><span>Future provider route; the quote, fees and delivery would be shown first.</span></button></div><div class="wallet-guide-bottom"><div><strong>${walletPreview?"Sample wallet preview ready":"No wallet connected"}</strong><span>${walletPreview?"This is only an example destination. No key, wallet or funds are held here.":"You can preview the connection step without installing a wallet."}</span></div>${btn(walletPreview?"Hide wallet preview":"Preview wallet connection","wallet-connect","secondary")}</div></section>`;}
 function dashboard(){if(!state.receiver.name)return receiver();const verified=state.receiver.verified;return `<div class="household-dashboard">${intro('HOUSEHOLD DASHBOARD',`Hello, ${esc(state.receiver.name)}.`,verified?'Your household profile is ready for this walkthrough.':'Set up your household now, before an emergency.') }<div class="dashboard-overview"><div><p class="eyebrow">YOUR NEXT STEP</p><h2>${verified?'You’re ready to follow a response.':'Complete your household checks.'}</h2><p>${verified?'Explore an affected-area example below, then see how a request is reviewed.':'A future service would privately check who you are, where you usually live, and which household or rented room you belong to.'}</p>${verified?btn('Review household details','edit-details','secondary'):btn('Start guided verification','verify-start','primary')}</div><div class="dashboard-status"><span>PROFILE STATUS</span><strong>${verified?'Example verified':'Setup in progress'}</strong><small>${verified?'All three walkthrough checks complete':'You can finish before any disaster is declared'}</small></div></div><div class="work-grid dashboard-grid"><section class="work-card"><div class="section-title"><h2>What verification checks</h2>${badge(verified?'Example complete':'3 steps',verified?'success':'')}</div><ol class="kyc-list"><li><span>01</span><div><strong>Identity</strong><p>Thai ID or passport and lawful residence evidence, reviewed privately in a future service.</p></div><em>${verified?'✓':'Next'}</em></li><li><span>02</span><div><strong>Usual residence</strong><p>Evidence that you lived in the affected area before the event. Evacuation does not erase your home address.</p></div><em>${verified?'✓':'Pending'}</em></li><li><span>03</span><div><strong>Your household or room</strong><p>A separate rented room may count as its own household; duplicates go to a person for review.</p></div><em>${verified?'✓':'Pending'}</em></li></ol>${verified?`<p class="private-summary"><strong>Private example:</strong> ${esc(state.receiver.residence)} · ${esc(state.receiver.room)}</p>`:btn('Continue verification','verify-start','secondary')}<p class="field-note">This walkthrough uses fictional details. No real KYC or document storage takes place.</p></section><section class="work-card response-card"><p class="eyebrow">RESPONSE STATUS</p><h2>${state.receiver.scenario==='before'?'Ready before a disaster':'Mae Rim flood example'}</h2><p>Choose a scenario to see what changes in your household dashboard.</p><div class="scenario-choice">${btn('Before a disaster','before',state.receiver.scenario==='before'?'primary':'secondary',!!state.claim)}${btn('Affected area','flood',state.receiver.scenario==='flood'?'primary':'secondary',!!state.claim)}</div><div class="eligibility review">${state.receiver.scenario==='before'?'<strong>No relief request is open.</strong><p>You can still create and verify your profile now. A serious affected-area response must be approved before a claim opens.</p>':`<strong>Fictional Mae Rim response open.</strong><p>This fictional response shows 0.8 SOL per household. A real event amount would be based on Thai essentials prices, then reviewed before requests open.</p>${state.claim?link('Track your request','tracking','primary'):verified?btn('Request household support','request-start','primary'):btn('Verify before requesting','verify-start','primary')}`}</div></section></div>${walletGuide()}</div>`;}
 function verification(){if(!state.receiver.name)return receiver();const labels=['Identity','Residence','Household'];return `${intro('GUIDED HOUSEHOLD SETUP',labels[step]+' check.', 'See the private evidence a real service would review. Use fictional details here.')} <section class="work-card verification-card"><ol class="steps">${labels.map((l,i)=>`<li ${i===step?'aria-current="step"':''}><span>${i+1}</span>${l}</li>`).join('')}</ol><div class="verification-context"><span>STEP ${step+1} OF 3</span><p>${['Identity helps stop one person opening multiple claims. A real service would check a Thai ID or passport and lawful residence as applicable.','Your usual home before a disaster matters more than your location after evacuation. A real reviewer could check a lease, bill, rent receipt or applicable residence record.','One grant is planned per household. A room number and dated rent receipt can help distinguish separate households inside one building.'][step]}</p></div><form id="verification-form">${step===0?`${field('name','Example display name',state.receiver.name)}<div class="document-sample"><strong>Future evidence: government ID</strong><p>This demo asks for no ID number, photo or upload. The future document check needs a qualified, private verification process.</p></div>`:step===1?`${field('residence','Usual residence before the event (example)',state.receiver.residence,'Fictional Mae Rim, Chiang Mai')}<div class="document-sample"><strong>Future evidence: proof of residence</strong><p>Examples include a dated rent receipt, lease or bill; a foreign resident might have a TM30 record. A reviewer would assess the evidence.</p></div>${edit?'<label class="checkbox"><input type="checkbox" style="width:auto" name="changed" value="yes"> This example residence changed after the fictional event</label>':''}`:`${field('room','Household / room identifier (example)',state.receiver.room,'Room A')}<div class="document-sample"><strong>Future evidence: household or rented room</strong><p>A dated monthly rent receipt may show a separate room. Shared building addresses and duplicates require human review.</p></div>`}<div class="button-row">${step>0?btn('Back','verify-back','secondary'):link('Back to dashboard','dashboard')}<button class="button primary">${step===2?'Finish example checks':'Continue'}</button></div></form></section>`;}
 function claimDetails(){return `${intro('REQUEST RELIEF','Confirm your household details.','Reuse your verification details. You can correct them before submitting.')}<section class="work-card"><h2>Fictional Mae Rim flood</h2><dl class="review"><dt>Example claimant</dt><dd>${esc(state.receiver.name)}</dd><dt>Usual residence</dt><dd>${esc(state.receiver.residence)}</dd><dt>Household / room</dt><dd>${esc(state.receiver.room)}</dd><dt>Fixed illustrative grant</dt><dd>0.8 SOL</dd></dl>${btn('Edit details','edit-details','secondary')}<form id="details-form"><label class="checkbox"><input type="checkbox" style="width:auto" required> These example details are correct</label><button class="button primary">Continue to payout preference</button></form>${sample()}</section>`;}
 function payment(){return `${intro('PAYOUT PREFERENCE','Choose how you would receive help.','These options explain the intended service. No money moves in this walkthrough.')}<section class="work-card"><form id="payment-form"><fieldset><legend>Preferred route</legend><label class="radio-card"><input type="radio" name="route" value="sol" ${state.receiver.route==='sol'?'checked':''}><span><strong>Keep SOL</strong><small>Illustrative delivery to your Solana wallet. Sample destination only.</small></span></label><label class="radio-card"><input type="radio" name="route" value="baht" ${state.receiver.route==='baht'?'checked':''}><span><strong>Convert to Thai baht</strong><small>Planned option · simulated. Provider, quote, fees and delivery still need investigation.</small></span></label></fieldset><p class="eligibility review">A future service could remember your explicit preference. This demo remembers it only until refresh/reset. Keeping SOL exposes its later value to price changes.</p><div class="button-row">${link('Back','claim-details')}<button class="button primary">Review request</button></div></form></section>`;}
 function claimReview(){return `${intro('REVIEW REQUEST','One grant for your household.','Check the example response and payout preference before continuing.')}<section class="work-card"><dl class="review"><dt>Response</dt><dd>Fictional Mae Rim flood</dd><dt>Grant</dt><dd>0.8 SOL · fictional example, not the final Thai-baht benchmark</dd><dt>Payout preference</dt><dd>${state.receiver.route==='sol'?'Keep SOL · sample wallet':'Thai baht · planned, simulated'}</dd><dt>Household details</dt><dd>Confirmed privately${state.receiver.changedResidence?' · address change requires human review':''}</dd></dl><p>One household grant per event. A request is not approval, and available event allocation still applies.</p>${sample()}<div class="button-row">${link('Change preference','payment')}${btn('Submit request','submit-claim')}</div></section>`;}
 const statusLabel=(s:ClaimStatus)=>({'submitted':'Submitted','review':'Under review','more':'More information needed','approved':'Approved','rejected':'Not approved','paid':'Demo payout complete'}[s]);
 function tracking(){const c=state.claim;if(!c)return `${intro('REQUEST TRACKING','No request submitted yet.','Complete the household walkthrough to see request tracking.')}${link('Open dashboard','dashboard','primary')}`;return `${intro('YOUR REQUEST',statusLabel(c.status), 'Fictional Mae Rim flood · sample request R-003')}<section class="work-grid"><div class="work-card"><h2>Request timeline</h2><ol class="timeline">${c.history.map(h=>`<li>${esc(h)}<small>Demonstration step · no real elapsed-time claim</small></li>`).join('')}</ol><p class="eligibility review">${esc(c.reason)}</p>${c.status==='submitted'?btn('Continue to review stage','under-review'):''}${['submitted','review','more'].includes(c.status)?`<p>The intended service would route this request to a human reviewer. Use the separate reviewer demo to explore that decision.</p>${link('Open reviewer demo','reviewer','primary')}`:''}${c.status==='more'?`${btn('Respond with sample clarification','clarify','secondary')}<p class="field-note">This represents an applicant response, not an actual document submission.</p>`:''}${c.status==='approved'?`${btn('Show demo payout outcome','complete-payout')}<p class="field-note">Completes an illustrative outcome only. No transfer or conversion is executed.</p>`:''}${c.status==='paid'?`<div class="receipt"><strong>Demo payout complete — no funds transferred</strong><p>Illustrative grant: 0.8 SOL</p><p>Route: ${c.route==='sol'?'Sample Solana wallet':'Future baht provider · simulated'}</p><p>Reference: SAMPLE-G003 · not a transaction signature.</p>${link('See sample public activity','activity','secondary')}</div>`:''}${c.status==='rejected'?'<p>In the intended service, the reason and an appeal path would be available. Reset to explore another fictional scenario; this is not a real eligibility decision.</p>':''}</div><aside class="work-card"><h2>What happens next?</h2><p>Human reviews handle uncertain residence or duplicate claims. A shared address alone does not establish a duplicate.</p><p>No guaranteed review time is demonstrated. The future 12–24 hour claim-to-payment goal remains a hypothesis to test.</p>${link('Household dashboard','dashboard')}${sample()}</aside></section>`;}
 function donate(){return `<div class="donor-page"><div class="donor-lead"><p class="eyebrow">DONATE TO RELIEF</p><h1 tabindex="-1">Keep help ready for the next household.</h1><p>Choose how much goes to the relief reserve. Operating support is separate and always optional.</p><div class="donor-proof"><strong>${publicResponse.households.toLocaleString('en-US')}</strong><span>households supported in this fictional Chiang Mai response</span></div><figure class="donor-scene"><img src="${householdConcept}" alt="Illustrative family choosing food and water after flooding"><figcaption>Illustrative scene · no real ReliefVue recipient</figcaption></figure></div><div class="donor-layout"><section class="donor-form-card"><h2>Your contribution</h2><form id="donor-form"><fieldset><legend>Choose a route</legend><label class="radio-card"><input type="radio" name="route" value="sol" ${donor.route==='sol'?'checked':''}><span><strong>Donate SOL</strong><small>Shown as a Solana wallet contribution.</small></span></label><label class="radio-card"><input type="radio" name="route" value="local" ${donor.route==='local'?'checked':''}><span><strong>Pay in local currency</strong><small>Planned provider route · simulated here.</small></span></label></fieldset><label for="amount">Choose a relief contribution</label><div class="donor-presets" role="group" aria-label="Suggested SOL amounts">${[.1,.25,.5,1].map(n=>`<button type="button" data-action="amount-${n}" aria-pressed="${donor.amount===n}" class="${donor.amount===n?'chosen':''}"><strong>${n} SOL</strong><small>${n===.1?'Start here':n===.25?'A little more':n===.5?'Give more':'Give generously'}</small></button>`).join('')}</div><div class="amount-input"><input id="amount" name="amount" type="number" min="0.001" max="10" step="0.001" value="${donor.amount}" required><span>SOL</span></div><p class="field-note">Choose any sample amount. You can review it before the demo receipt; no wallet or payment is connected.</p><div class="donor-support"><div><h3>Support ReliefVue operations</h3><p>Optional and separate from household relief.</p></div><label for="support">Optional amount in SOL</label><input id="support" name="support" type="number" min="0" max="1" step="0.001" value="${donor.support}" required></div><button class="button primary donor-submit">Review contribution <span aria-hidden="true">→</span></button></form></section><aside class="donor-impact"><p class="eyebrow">WHERE IT GOES</p><h2>Your gift joins the relief reserve.</h2><p>In the planned service, donations fill a dedicated SOL reserve before an emergency. Approved household grants leave that reserve, with each movement visible in the public record.</p><ol class="donor-flow"><li><span>01</span><div><strong>Keep funds ready</strong><small>Contributions enter the dedicated relief reserve.</small></div></li><li><span>02</span><div><strong>Review a response</strong><small>People approve an affected area, household checks and a fixed grant.</small></div></li><li><span>03</span><div><strong>Show every movement</strong><small>Example grants of ${sol(publicResponse.grant)} SOL leave for verified wallets.</small></div></li></ol><a href="#activity">Follow sample fund activity ↗</a><small>The Chiang Mai response is fictional. A real household grant would be set from Thai essentials prices; conversion and payment providers are not connected.</small></aside></div></div>`;}
 function donorReview(){return `${intro('REVIEW CONTRIBUTION','See exactly what supports relief.','This is a simulated checkout. No payment details are collected.')}<section class="work-card"><dl class="review"><dt>Contribution route</dt><dd>${donor.route==='sol'?'SOL · sample wallet':'Local currency · proposed future integration'}</dd><dt>Relief reserve</dt><dd>${sol(donor.amount)} SOL</dd><dt>Separate operating wallet</dt><dd>${sol(donor.support)} SOL</dd><dt>Total sample contribution</dt><dd>${sol(Math.round((donor.amount+donor.support)*1e9)/1e9)} SOL</dd><dt>Network / provider fees</dt><dd>Not calculated in this demo; a real checkout would disclose applicable fees and net amounts.</dd></dl>${donor.route==='local'?'<p class="eligibility review">Future provider technology, exchange quote, fees and delivery remain to be validated. No equivalent local-currency amount is invented here.</p>':''}<div class="button-row">${link('Edit amounts','donate')}${btn('Confirm contribution','confirm-donation')}</div>${sample()}</section>`;}
 function donorReceipt(){const r=state.donorReceipt;if(!r)return donate();return `${intro('DEMO RECEIPT','Thank you for exploring the idea.','Your sample contribution illustrates how the reserve and operating support are separated.')}<section class="form-panel receipt"><strong>Demo contribution complete — no funds transferred</strong><dl class="review"><dt>Sample reference</dt><dd>${esc(r.ref)} · not a blockchain signature</dd><dt>Relief reserve</dt><dd>${sol(r.amount)} SOL</dd><dt>Optional operating support</dt><dd>${sol(r.support)} SOL</dd><dt>Payment route</dt><dd>${r.route==='sol'?'Sample SOL wallet':'Local currency · future feature, simulated'}</dd></dl><p>No account was created. Sample activity exists only in this page until refresh/reset.</p><div class="button-row">${link('Follow sample fund activity','activity','primary')}${link('Back to home','home')}</div></section>`;}
 function reviewer(){const current=state.claim;return `${intro('REVIEW QUEUE','Household and event review.','Check example evidence, record a reason and follow the status of each case.')}<div class="work-grid"><section class="work-card"><h2>Household request queue</h2><p>Entered visitor details are not copied here. The current walkthrough appears as an anonymous sample request.</p><div class="queue"><button data-action="case-current"><strong>R-003 · Current walkthrough</strong><span>${current?statusLabel(current.status):'Not submitted'}</span></button><button data-action="case-room"><strong>R-002 · Separate rented room</strong><span>Seeded example · residence review</span></button><button data-action="case-duplicate"><strong>R-004 · Possible duplicate</strong><span>Seeded example · human comparison needed</span></button></div><div class="review-detail"><h3>${reviewCase==='current'?'R-003 · Current sample request':reviewCase==='room'?'R-002 · Independent rented room':'R-004 · Possible household duplicate'}</h3><dl class="review"><dt>Identity evidence</dt><dd>Fictional sample · no real ID</dd><dt>Usual residence</dt><dd>Fictional Mae Rim area</dd><dt>Household signal</dt><dd>${reviewCase==='duplicate'?'Room matches an existing seeded claim; investigate, do not auto-ban.':reviewCase==='room'?'Distinct rented room in a shared building; may be a separate household.':state.receiver.changedResidence?'Residence changed after the event; inspect the exception.':'Scripted household check'}</dd><dt>Evidence</dt><dd>Sample monthly rent receipt and example residence record. Not real documents.</dd></dl><form id="review-form"><label for="decision">Review decision</label><select id="decision" name="decision"><option value="approve" ${decision==='approve'?'selected':''}>Approve sample request</option><option value="more" ${decision==='more'?'selected':''}>Request more information</option><option value="reject" ${decision==='reject'?'selected':''}>Reject with reason</option></select><label for="reason">Reason (use example text only)</label><textarea id="reason" name="reason" maxlength="400" required placeholder="Explain the example evidence and decision"></textarea><button class="button primary" ${reviewCase==='current'&&(!current||!['submitted','review','more'].includes(current.status))?'disabled':''}>Record demo review</button></form></div></section><aside class="work-card"><h2>Disaster evidence review</h2><p><strong>Fictional observation:</strong> homes inundated and essential access cut in Mae Rim. This is a fixture, not a scraped news report.</p><p>AI could gather leads in a future service. People must check authenticity, time, location, independent corroboration and conflicting evidence.</p><p>${badge(state.event)} Reviewer: ${state.reviewerApproved?'recommended':'waiting'} · Approver: ${state.approver||'waiting'}</p><div class="button-row">${btn('Start Watching','watch','secondary',!!state.claim)}${btn('Review observed flood fixture','evidence','secondary',!!state.claim)}${btn('Reviewer recommends response','recommend','secondary',state.event!=='review'||!!state.claim)}${btn('Primary approves event','authorize-primary','secondary',!state.reviewerApproved||!!state.claim)}${btn('Backup approves event','authorize-backup','secondary',!state.reviewerApproved||!!state.claim)}</div><p class="field-note">Independent review plus primary or formally appointed backup authorization of the same event terms. These controls simulate that separation; they do not sign a program transaction.</p>${link('Return to request tracking','tracking')}${sample()}</aside></div>`;}
 function about(){return `${intro('PROTOTYPE BOUNDARIES','An idea you can experience.','A hackathon demonstration, with the future service separated from the prototype.')}<div class="work-grid"><section class="work-card"><h2>Working in this walkthrough</h2><ul><li>Guided receiver, donor and reviewer screens.</li><li>Temporary form entries and scripted request decisions.</li><li>Sample reserve accounting and public activity.</li><li>No wallet, account or network required to explore.</li></ul><h2>Proposed for a funded phase</h2><ul><li>Real identity, residence and household verification.</li><li>Qualified fiat/custody providers and recovery.</li><li>Live evidence gathering, staff roles and governance.</li><li>Security-reviewed reserve and controlled pilot.</li></ul></section><section class="work-card"><h2>Blockchain evidence</h2><p>The optional Devnet tools are separate from this walkthrough. An Explorer receipt is shown only after a real confirmed test transaction.</p><p>Reserve contract source exists but is not compiled or deployed. Local server transfer rules are not on-chain custody enforcement.</p><p>ReliefVue is a provisional name. This demo has an English/Thai interface preview; real service language and accessibility review remain future work.</p><a class="button secondary" href="#technical">Open optional Devnet tools</a></section></div>`;}
 const pages:Record<string,()=>string>={home,overview:home,how,receiver,request:receiver,recovery,dashboard,verification,'claim-details':claimDetails,payment,'claim-review':claimReview,tracking,donate,'donor-review':donorReview,'donor-receipt':donorReceipt,reviewer,operator:reviewer,activity:()=>`<div class="activity-screen">${intro('FUND ACTIVITY','Follow the Chiang Mai response.','Reserve, household grants and wallet destinations in one public view.')}<p class="scenario-label">Fictional response data</p>${activityCharts()}${activityTable()}</div>`,about};
 function alertStrip(){const group=(duplicate=false)=>`<div class="alert-ticker-group" ${duplicate?'aria-hidden="true"':''}>${scenarioAlerts.map(([label,title,source])=>`<div class="alert-story"><span class="alert-type">${esc(label)}</span><strong class="alert-title">${esc(title)}</strong><span class="alert-source">${esc(source)}</span></div>`).join('')}</div>`;return `<div class="alert-strip" aria-label="Fictional scenario alerts"><div class="alert-inner"><div class="alert-flag"><span class="alert-icon" aria-hidden="true">!</span><span class="alert-label">SCENARIO ALERT</span><small>EXAMPLE · NOT LIVE</small></div><div class="alert-ticker-window" aria-label="Four fictional alerts moving left"><div class="alert-ticker-track ${alertsPaused?'is-paused':''}">${group()}${group(true)}</div></div><a class="alert-link" href="#how">How a response opens ↗</a><div class="alert-actions"><button type="button" data-action="alert-pause" aria-pressed="${alertsPaused}">${alertsPaused?"Play":"Pause"}</button></div></div></div>`;}
 function render(focus=false){if(!pages[page])page='home';if(['verification','claim-details','payment','claim-review'].includes(page)&&!state.receiver.name)page='receiver';if(['claim-details','payment','claim-review'].includes(page)&&!state.receiver.verified)page='dashboard';
 app.innerHTML=`<div class="demo-banner"><strong>DEMO MODE</strong><span>Fictional Chiang Mai response · no real accounts or payments</span><a class="demo-staff-link" href="#reviewer">Reviewer view</a><button data-action="reset">Reset demo</button></div><div class="site-chrome"><header class="header"><div class="header-inner"><nav aria-label="Main"><button data-action="nav-how">How it works</button><button data-action="nav-activity">Fund activity</button></nav><a class="wordmark" href="#home" aria-label="ReliefVue home"><img class="brand-symbol" src="${selectedLogoSource}" alt="ReliefVue elephant"><span>ReliefVue</span></a><div class="header-actions"><div class="language-switch" role="group" aria-label="Language"><button type="button" data-action="lang-en" aria-pressed="${locale==='en'}">EN</button><button type="button" data-action="lang-th" aria-pressed="${locale==='th'}">TH</button></div><a href="#receiver">Get help</a><a class="button primary" href="#donate">Donate</a></div></div></header>${alertStrip()}</div><main id="main" class="container">${message?`<p class="feedback" role="status">${esc(message)}</p>`:''}${pages[page]!()}</main><footer class="footer"><div class="container footer-layout"><div class="footer-identity"><a href="#home" class="footer-logo" aria-label="ReliefVue home"><img src="${selectedLogoSource}" alt=""><span>ReliefVue</span></a><h2>Ready before the flood.<br>Accountable after every grant.</h2><p>ReliefVue is a proposed Thailand-first way to prepare a SOL reserve, review household requests privately, and show every grant movement publicly.</p></div><div class="footer-next"><p>See the journey as a household or donor.</p><div class="footer-actions"><a class="button primary" href="#receiver">Prepare your household</a><a class="button secondary" href="#donate">Support the reserve</a></div></div><div class="footer-links"><a href="#how">How it works</a><a href="#activity">Fund activity</a><a href="#reviewer">Reviewer view</a></div><div class="footer-foot"><span>Thailand first · English / ไทย</span><span>Hackathon demo · fictional accounts, response and payments</span></div></div></footer>`;
 bind();localize(app,locale);if(focus){app.querySelector<HTMLElement>('h1')?.focus();window.scrollTo({top:0,behavior:'instant'});}}
 function action(work:()=>void){try{work();}catch(e){message=e instanceof Error?e.message:String(e);render();}}
 function bind(){app.querySelectorAll<HTMLButtonElement>('[data-action]').forEach(b=>b.onclick=()=>action(()=>{
 const a=b.dataset.action!;if(a==='lang-en'||a==='lang-th'){locale=a==='lang-th'?'th':'en';render();return;}if(a.startsWith('nav-')){go(a.slice(4));return;}
 if(a==='alert-pause'){alertsPaused=!alertsPaused;b.textContent=alertsPaused?'Play':'Pause';b.setAttribute('aria-pressed',String(alertsPaused));app.querySelector('.alert-ticker-track')?.classList.toggle('is-paused',alertsPaused);return;}
 if(a==='ledger-pause'){replayPaused=!replayPaused;b.textContent=replayPaused?'Resume replay':'Pause replay';b.setAttribute('aria-pressed',String(replayPaused));return;}
 if(a.startsWith('ledger-')){ledgerFilter=a.slice(7) as 'all'|'grants'|'donations';render();return;}
 if(a.startsWith('amount-')){donor.amount=Number(a.slice(7));render();return;}
 if(a==='reset'){walletPreview=false;state=createDemo();donor={route:'sol',amount:.25,support:0};step=0;edit=false;entry='create';reviewCase='current';go('home');return;}
 if(a==='create'||a==='signin'){entry=a;render();}
 if(a==='wallet-connect'){walletPreview=!walletPreview;render();return;}if(a==='wallet-route-sol'||a==='wallet-route-baht'){state.receiver.route=a==='wallet-route-sol'?'sol':'baht';render();return;}
  if(a==='sample-profile'){state.receiver.name='Demo neighbour';go('dashboard');}
 if(a==='verify-start'){edit=false;step=0;go('verification');}
 if(a==='edit-details'){if(state.claim)throw Error('A submitted request needs reviewer clarification; reset to explore a different household.');edit=true;step=1;go('verification');}
 if(a==='verify-back'){step--;render(true);}
 if(a==='before'||a==='flood'){if(state.claim)throw Error('Reset before changing a submitted scenario.');state.receiver.scenario=a;state.event=a==='flood'?'active':'prepared';state.reviewerApproved=a==='flood';state.approver=a==='flood'?'primary':null;render();}
 if(a==='request-start'){if(!state.receiver.verified)throw Error('Continue verification first.');go('claim-details');}
 if(a==='submit-claim'){submitClaim(state);go('tracking');}
 if(a==='under-review'){if(state.claim?.status==='submitted'){state.claim.status='review';state.claim.history.push('Under review');state.claim.reason='A human reviewer would check the household evidence.';}render();}
 if(a==='clarify'){if(state.claim?.status==='more'){state.claim.status='review';state.claim.history.push('Sample clarification received');state.claim.reason='Sample clarification ready for a human decision.';}render();}
 if(a==='complete-payout'){completePayout(state);render(true);}
 if(a==='confirm-donation'){donateSample(state,donor.amount,donor.support,donor.route);go('donor-receipt');}
 if(a.startsWith('case-')){reviewCase=a.slice(5);render();}
 if(['watch','evidence','recommend','authorize-primary','authorize-backup'].includes(a)){
 if(state.claim)throw Error('Existing request preserves the example event terms. Reset for another evidence scenario.');
 if(a==='watch'||a==='evidence'){state.event=a==='watch'?'watching':'review';state.reviewerApproved=false;state.approver=null;}
 if(a==='recommend'){if(state.event!=='review')throw Error('Review the observed evidence first.');state.reviewerApproved=true;}
 if(a.startsWith('authorize')){if(!state.reviewerApproved)throw Error('Independent reviewer recommendation required.');state.event='active';state.approver=a==='authorize-primary'?'primary':'backup';}
 render();}
 }));
 app.querySelector<HTMLFormElement>('#entry-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);state.receiver.name=String(f.get('name')||'').trim();go('dashboard');});
 app.querySelector<HTMLFormElement>('#verification-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);if(step===0)state.receiver.name=String(f.get('name')||'').trim();if(step===1){state.receiver.residence=String(f.get('residence')||'').trim();if(edit)state.receiver.changedResidence=f.has('changed');}if(step===2){state.receiver.room=String(f.get('room')||'').trim();state.receiver.verified=true;go('dashboard');}else{step++;render(true);}});
 app.querySelector<HTMLFormElement>('#details-form')?.addEventListener('submit',e=>{e.preventDefault();go('payment');});
 app.querySelector<HTMLFormElement>('#payment-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);state.receiver.route=f.get('route')==='baht'?'baht':'sol';go('claim-review');});
 app.querySelector<HTMLFormElement>('#donor-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);donor={route:f.get('route')==='local'?'local':'sol',amount:Number(f.get('amount')),support:Number(f.get('support'))};go('donor-review');});
 app.querySelector<HTMLFormElement>('#review-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget as HTMLFormElement);decision=String(f.get('decision'));action(()=>{if(reviewCase==='current'){decideClaim(state,decision as 'approve'|'more'|'reject',String(f.get('reason')||''));go('tracking');}else{message='Seeded example decision noted in this open page only; no live claim or user was affected.';render();}});});
 }
 window.addEventListener('hashchange',()=>{if(location.hash==='#technical'){location.reload();return;}page=location.hash.slice(1)||'home';message='';render(true);});render();
}
